"use strict";(globalThis.webpackChunkmy_docusaurus=globalThis.webpackChunkmy_docusaurus||[]).push([[9724],{6048(n){n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"tim-hieu-Java-platform","metadata":{"permalink":"/my-docusaurus/blog/tim-hieu-Java-platform","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2026-11-02-tim-hieu-ve-Java.md","source":"@site/blog/2026-11-02-tim-hieu-ve-Java.md","title":"T\xecm hi\u1ec3u Java Platform \u2013 Execution Flow & JVM Architecture","description":"1. Java Platform Overview \u2013 T\u1ed5ng quan n\u1ec1n t\u1ea3ng Java","date":"2026-11-02T00:00:00.000Z","tags":[{"inline":true,"label":"java","permalink":"/my-docusaurus/blog/tags/java"},{"inline":true,"label":"jvm","permalink":"/my-docusaurus/blog/tags/jvm"},{"inline":true,"label":"bytecode","permalink":"/my-docusaurus/blog/tags/bytecode"},{"inline":true,"label":"jdk","permalink":"/my-docusaurus/blog/tags/jdk"},{"inline":true,"label":"jre","permalink":"/my-docusaurus/blog/tags/jre"},{"inline":true,"label":"jit","permalink":"/my-docusaurus/blog/tags/jit"},{"inline":true,"label":"execution-flow","permalink":"/my-docusaurus/blog/tags/execution-flow"}],"readingTime":4.4,"hasTruncateMarker":false,"authors":[{"name":"Mai Duc Anh","title":"Blogger & Developer","url":"https://github.com/maiducanha1anh","imageURL":"https://github.com/yourusername.png","key":"admin","page":null}],"frontMatter":{"slug":"tim-hieu-Java-platform","title":"T\xecm hi\u1ec3u Java Platform \u2013 Execution Flow & JVM Architecture","authors":["admin"],"tags":["java","jvm","bytecode","jdk","jre","jit","execution-flow"]},"unlisted":false,"nextItem":{"title":"Ph\xe2n t\xedch c\u01a1 ch\u1ebf ho\u1ea1t \u0111\u1ed9ng c\u1ee7a JVM qua \u0111o\u1ea1n code c\u1ee5 th\u1ec3","permalink":"/my-docusaurus/blog/phan-tich-JVM"}},"content":"## 1. Java Platform Overview \u2013 T\u1ed5ng quan n\u1ec1n t\u1ea3ng Java\\r\\n\\r\\nJava kh\xf4ng ch\u1ec9 l\xe0 **m\u1ed9t ng\xf4n ng\u1eef l\u1eadp tr\xecnh**, m\xe0 l\xe0 **m\u1ed9t n\u1ec1n t\u1ea3ng ho\xe0n ch\u1ec9nh (Java Platform)**.\\r\\n\\r\\n\ud83d\udc49 Khi n\xf3i *\u201cl\u1eadp tr\xecnh Java\u201d*, th\u1ef1c ch\u1ea5t ta \u0111ang l\xe0m vi\u1ec7c v\u1edbi **3 th\xe0nh ph\u1ea7n c\u1ed1t l\xf5i**:\\r\\n\\r\\n- **Java Language**\\r\\n- **JVM (Java Virtual Machine)**\\r\\n- **H\u1ec7 sinh th\xe1i th\u01b0 vi\u1ec7n & c\xf4ng c\u1ee5**\\r\\n\\r\\n### M\u1ee5c ti\xeau c\u1ed1t l\xf5i c\u1ee7a Java\\r\\n\\r\\n> **Write Once, Run Anywhere (WORA)**\\r\\n\\r\\nVi\u1ebft code **m\u1ed9t l\u1ea7n**, ch\u1ea1y \u0111\u01b0\u1ee3c tr\xean:\\r\\n- Windows\\r\\n- Linux\\r\\n- macOS  \\r\\n\u2026 m\xe0 **kh\xf4ng c\u1ea7n s\u1eeda code**\\r\\n\\r\\n---\\r\\n\\r\\n## 2. Vai tr\xf2 c\u1ee7a JDK, JRE, JVM\\r\\n\\r\\nR\u1ea5t nhi\u1ec1u ng\u01b0\u1eddi h\u1ecdc Java **b\u1ecb nh\u1ea7m l\u1eabn 3 kh\xe1i ni\u1ec7m n\xe0y**, n\xean c\u1ea7n l\xe0m r\xf5 tuy\u1ec7t \u0111\u1ed1i.\\r\\n\\r\\n### 2.1 JVM \u2013 Java Virtual Machine\\r\\n\\r\\n**JVM l\xe0 g\xec?**\\r\\n\\r\\n- JVM l\xe0 **m\xe1y \u1ea3o**\\r\\n- Ch\u1ea1y **bytecode Java**\\r\\n- \u0110\xf3ng vai tr\xf2 **trung gian gi\u1eefa Java v\xe0 h\u1ec7 \u0111i\u1ec1u h\xe0nh**\\r\\n\\r\\n\ud83d\udccc JVM:\\r\\n- Kh\xf4ng hi\u1ec3u `.java`\\r\\n- Kh\xf4ng hi\u1ec3u `.exe`\\r\\n- **Ch\u1ec9 hi\u1ec3u `.class` (bytecode)**\\r\\n\\r\\n\ud83d\udc49 M\u1ed7i h\u1ec7 \u0111i\u1ec1u h\xe0nh c\xf3 **JVM ri\xeang**, nh\u01b0ng:\\r\\n- Bytecode th\xec **gi\u1ed1ng nhau**\\r\\n\\r\\n---\\r\\n\\r\\n### 2.2 JRE \u2013 Java Runtime Environment\\r\\n\\r\\n**JRE g\u1ed3m:**\\r\\n\\r\\n- JVM\\r\\n- Core Java Libraries (java.lang, java.util, ...)\\r\\n- C\xe1c file c\u1ea5u h\xecnh runtime\\r\\n\\r\\n\ud83d\udc49 JRE d\xf9ng \u0111\u1ec3:\\r\\n- **Ch\u1ea1y ch\u01b0\u01a1ng tr\xecnh Java**\\r\\n- \u274c Kh\xf4ng d\xf9ng \u0111\u1ec3 vi\u1ebft hay bi\xean d\u1ecbch code\\r\\n\\r\\n\ud83d\udccc N\u1ebfu m\xe1y ch\u1ec9 c\xf3 JRE:\\r\\n- Ch\u1ea1y \u0111\u01b0\u1ee3c `.class`\\r\\n- \u274c Kh\xf4ng bi\xean d\u1ecbch \u0111\u01b0\u1ee3c `.java`\\r\\n\\r\\n---\\r\\n\\r\\n### 2.3 JDK \u2013 Java Development Kit\\r\\n\\r\\n**JDK = JRE + C\xf4ng c\u1ee5 ph\xe1t tri\u1ec3n**\\r\\n\\r\\nBao g\u1ed3m:\\r\\n- `javac` (compiler)\\r\\n- `java` (launcher)\\r\\n- `javadoc`, `jdb`, ...\\r\\n\\r\\n\ud83d\udc49 JDK d\xf9ng \u0111\u1ec3:\\r\\n- Vi\u1ebft code\\r\\n- Bi\xean d\u1ecbch\\r\\n- Ch\u1ea1y\\r\\n- Debug\\r\\n\\r\\n\ud83d\udccc Khi c\xe0i Java \u0111\u1ec3 h\u1ecdc l\u1eadp tr\xecnh:\\r\\n\u27a1\ufe0f **LU\xd4N c\u1ea7n JDK**\\r\\n\\r\\n---\\r\\n\\r\\n### 2.4 M\u1ed1i quan h\u1ec7 t\u1ed5ng th\u1ec3\\r\\nJDK <br />\\r\\n\u251c\u2500\u2500 JRE <br />\\r\\n\u2502   \u251c\u2500\u2500 JVM <br />\\r\\n\u2502   \u2514\u2500\u2500 Java Core Libraries <br />\\r\\n\u2514\u2500\u2500 Development Tools <br />\\r\\n\\r\\n---\\r\\n## 3. M\u1ed1i quan h\u1ec7 gi\u1eefa Java Language v\xe0 Java Platform\\r\\n### Java Language\\r\\n- C\xfa ph\xe1p v\xe0 t\u1eeb kh\xf3a\\r\\n- Ki\u1ec3u d\u1eef li\u1ec7u\\r\\n- OOP (class, object, inheritance)\\r\\n- File m\xe3 ngu\u1ed3n `.java`\\r\\n\\r\\n### Java Platform\\r\\n- JVM (Java Virtual Machine)\\r\\n- ClassLoader Subsystem\\r\\n- Runtime Data Areas\\r\\n- Execution Engine & Garbage Collector\\r\\n\\r\\n**Java Language ch\u1ec9 l\xe0 ph\u1ea7n n\u1ed5i**  \\r\\n **Java Platform m\u1edbi l\xe0 th\u1ee9 quy\u1ebft \u0111\u1ecbnh ch\u01b0\u01a1ng tr\xecnh ch\u1ea1y th\u1ebf n\xe0o**\\r\\n\\r\\n ---\\r\\n\\r\\n## 4. Java Execution Flow \u2013 Lu\u1ed3ng th\u1ef1c thi c\u1ee7a Java\\r\\n\\r\\nKhi b\u1ea1n ch\u1ea1y m\u1ed9t ch\u01b0\u01a1ng tr\xecnh Java, **JVM kh\xf4ng th\u1ef1c thi tr\u1ef1c ti\u1ebfp file `.java`**.\\r\\n\\r\\n### Lu\u1ed3ng t\u1ed5ng qu\xe1t\\r\\n\\r\\nIDE  <br />\\r\\n\u2193 (Save)  <br />\\r\\n`Hello.java` (\u1ed4 c\u1ee9ng) <br /> \\r\\n\u2193 (Compile)  <br />\\r\\n`javac Hello.java`  <br />\\r\\n\u2193  <br />\\r\\n`Hello.class` (Bytecode)  <br />\\r\\n\u2193  <br />\\r\\nJVM (RAM)  <br />\\r\\n\u2193  <br />\\r\\nOS  <br />\\r\\n\u2193  <br />\\r\\nCPU th\u1ef1c thi  <br />\\r\\n\\r\\n---\\r\\n\\r\\n## 5. Compile-time v\xe0 Runtime trong Java\\r\\n\\r\\n### 5.1 Compile-time\\r\\n\\r\\n**X\u1ea3y ra khi ch\u1ea1y:**\\r\\n\\r\\n```bash\\r\\njavac Hello.java\\r\\n```\\r\\n\u0110\u1ea7u v\xe0o:\\r\\n\\r\\nFile .java (source code)\\r\\n\\r\\nJava l\xe0m g\xec?\\r\\n-Ki\u1ec3m tra c\xfa ph\xe1p\\r\\n-Ki\u1ec3m tra ki\u1ec3u d\u1eef li\u1ec7u\\r\\n-Bi\xean d\u1ecbch sang bytecode\\r\\n\\r\\n\u0110\u1ea7u ra:\\r\\n-File .class\\r\\n\\r\\n\ud83d\udccc Compile-time kh\xf4ng ch\u1ea1y ch\u01b0\u01a1ng tr\xecnh\\r\\n\\r\\n### 5.2 Runtime\\r\\n\\r\\nX\u1ea3y ra khi ch\u1ea1y:\\r\\n```bash\\r\\njava Hello\\r\\n```\\r\\n\\r\\n\\r\\n\u0110\u1ea7u v\xe0o:\\r\\n-File .class\\r\\n\\r\\nJava l\xe0m g\xec?\\r\\n-JVM load class\\r\\n-Ki\u1ec3m tra bytecode\\r\\n\\r\\nTh\u1ef1c thi\\r\\n\ud83d\udccc Runtime m\u1edbi l\xe0 l\xfac ch\u01b0\u01a1ng tr\xecnh th\u1ef1c s\u1ef1 ch\u1ea1y\\r\\n\\r\\n## 6. Bytecode l\xe0 g\xec? V\xec sao Java portable?\\r\\n\\r\\nBytecode l\xe0 g\xec?\\r\\n-L\xe0 m\xe3 trung gian\\r\\n-Kh\xf4ng ph\u1ea3i m\xe3 m\xe1y\\r\\n-Kh\xf4ng ph\u1ee5 thu\u1ed9c OS hay CPU\\r\\n\\r\\n\ud83d\udccc Bytecode:\\r\\n-Ch\u1ea1y tr\xean JVM\\r\\n-JVM d\u1ecbch ti\u1ebfp sang m\xe3 m\xe1y\\r\\n\\r\\nV\xec sao Java ch\u1ea1y \u0111a n\u1ec1n t\u1ea3ng?\\r\\n\\r\\nJava Source (.java)<br />\\r\\n        \u2193<br />\\r\\n   Bytecode (.class)<br />\\r\\n        \u2193<br />\\r\\n \u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510 <br />\\r\\n \u2502 JVM Windows \u2502 \u2192 CPU Windows <br />\\r\\n \u2502 JVM Linux   \u2502 \u2192 CPU Linux <br />\\r\\n \u2502 JVM macOS   \u2502 \u2192 CPU macOS <br />\\r\\n \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\\r\\n\\r\\n\\r\\n\ud83d\udc49 Kh\xf4ng ph\u1ea3i Java ch\u1ea1y tr\u1ef1c ti\u1ebfp tr\xean OS\\r\\n\ud83d\udc49 JVM m\u1edbi l\xe0 th\u1ee9 ch\u1ea1y tr\xean OS\\r\\n\\r\\n## 7. JVM Architecture \u2013 Ki\u1ebfn tr\xfac JVM\\r\\n\\r\\nJVM g\u1ed3m 3 kh\u1ed1i l\u1edbn:\\r\\n-ClassLoader Subsystem\\r\\n-Runtime Data Areas\\r\\n-Execution Engine\\r\\n\\r\\n## 8. ClassLoader Subsystem\\r\\n\\r\\nNhi\u1ec7m v\u1ee5:\\r\\n-Load .class v\xe0o JVM\\r\\n-Ki\u1ec3m tra t\xednh h\u1ee3p l\u1ec7\\r\\n-Chu\u1ea9n b\u1ecb class \u0111\u1ec3 ch\u1ea1y\\r\\n\\r\\n### C\xe1c lo\u1ea1i ClassLoader trong JVM\\r\\n\\r\\n- **Bootstrap ClassLoader**  \\r\\n  Load c\xe1c core class c\u1ee7a Java (v\xed d\u1ee5: `java.lang`, `java.util`)\\r\\n\\r\\n- **Platform ClassLoader** *(Java 9+)*  \\r\\n  Load c\xe1c th\u01b0 vi\u1ec7n thu\u1ed9c Java Platform (v\xed d\u1ee5: `java.sql`, `java.xml`)\\r\\n\\r\\n- **Application ClassLoader**  \\r\\n  Load c\xe1c class do l\u1eadp tr\xecnh vi\xean vi\u1ebft (classpath)\\r\\n\ud83d\udccc Class ch\u1ec9 \u0111\u01b0\u1ee3c load khi c\u1ea7n thi\u1ebft\\r\\n\\r\\n## 9. Runtime Data Areas \u2013 V\xf9ng nh\u1edb trong JVM\\r\\n\\r\\n### 9.1 Method Area\\r\\n\\r\\nL\u01b0u:\\r\\n-Class metadata\\r\\n-Method info\\r\\n-Static variables\\r\\n\\r\\n### 9.2 Heap\\r\\n\\r\\n-L\u01b0u object\\r\\n-D\xf9ng chung cho to\xe0n JVM\\r\\n-Do Garbage Collector qu\u1ea3n l\xfd\\r\\n\\r\\n### 9.3 Stack\\r\\n\\r\\nM\u1ed7i thread c\xf3 stack ri\xeang\\r\\n\\r\\nL\u01b0u:\\r\\n-Local variables\\r\\n-Method call\\r\\n-Reference\\r\\n\\r\\n\ud83d\udccc Stack nh\u1ecf, nhanh\\r\\n\ud83d\udccc Heap l\u1edbn, ch\u1eadm h\u01a1n\\r\\n\\r\\n### 9.4 PC Register\\r\\n\\r\\nL\u01b0u \u0111\u1ecba ch\u1ec9 instruction \u0111ang ch\u1ea1y\\r\\n\\r\\n### 9.5 Native Method Stack\\r\\n\\r\\nD\xf9ng cho code native (C/C++)\\r\\n\\r\\n## 10. Execution Engine \u2013 B\u1ed9 m\xe1y th\u1ef1c thi\\r\\n### 10.1 Interpreter\\r\\n\\r\\n\u0110\u1ecdc bytecode\\r\\n\\r\\nTh\u1ef1c thi t\u1eebng instruction\\r\\n\\r\\n\ud83d\udccc \u01afu \u0111i\u1ec3m:\\r\\n-Ch\u1ea1y ngay\\r\\n\\r\\n\ud83d\udccc Nh\u01b0\u1ee3c \u0111i\u1ec3m:\\r\\n-Ch\u1eadm n\u1ebfu ch\u1ea1y l\u1eb7p nhi\u1ec1u l\u1ea7n\\r\\n\\r\\n### 10.2 JIT Compiler (Just-In-Time)\\r\\n\\r\\nJIT l\xe0m g\xec?\\r\\n-Ph\xe1t hi\u1ec7n \u0111o\u1ea1n code ch\u1ea1y nhi\u1ec1u\\r\\n-Bi\xean d\u1ecbch bytecode \u2192 m\xe3 m\xe1y\\r\\n-Cache l\u1ea1i \u0111\u1ec3 d\xf9ng sau\\r\\n\\r\\n\ud83d\udccc JVM hi\u1ec7n \u0111\u1ea1i:\\r\\n-Interpreter + JIT\\r\\n-T\u1ef1 t\u1ed1i \u01b0u khi ch\u01b0\u01a1ng tr\xecnh ch\u1ea1y\\r\\n\\r\\n## 11. T\u1ed5ng k\u1ebft\\r\\n\\r\\nTham kh\u1ea3o slide chi ti\u1ebft t\u1ea1i \u0111\xe2y :\\r\\n- \ud83d\udd17 https://www.canva.com/design/DAHApyPYZmw/AQAchpZL_3B77rpOe4-3YQ/edit\\r\\n\\r\\nJava kh\xf4ng \u0111\u01a1n thu\u1ea7n l\xe0 m\u1ed9t ng\xf4n ng\u1eef, m\xe0 l\xe0 m\u1ed9t n\u1ec1n t\u1ea3ng ho\xe0n ch\u1ec9nh g\u1ed3m JDK, JRE v\xe0 JVM. Ch\u01b0\u01a1ng tr\xecnh Java kh\xf4ng ch\u1ea1y tr\u1ef1c ti\u1ebfp tr\xean h\u1ec7 \u0111i\u1ec1u h\xe0nh m\xe0 ph\u1ea3i tr\u1ea3i qua qu\xe1 tr\xecnh bi\xean d\u1ecbch sang bytecode, sau \u0111\xf3 \u0111\u01b0\u1ee3c JVM th\xf4ng d\u1ecbch v\xe0 t\u1ed1i \u01b0u b\u1eb1ng JIT tr\u01b0\u1edbc khi CPU th\u1ef1c thi.\\r\\n\\r\\nVi\u1ec7c hi\u1ec3u r\xf5:\\r\\n\\r\\n-Java Platform <br/>\\r\\n-Execution Flow <br/>\\r\\n-JVM Architecture <br/>\\r\\n\\r\\ngi\xfap l\u1eadp tr\xecnh vi\xean:\\r\\n\\r\\n-Hi\u1ec3u s\xe2u b\u1ea3n ch\u1ea5t Java <br/>\\r\\n-Debug t\u1ed1t h\u01a1n <br/>\\r\\n-Vi\u1ebft code t\u1ed1i \u01b0u h\u01a1n <br/>\\r\\n-C\xf3 n\u1ec1n t\u1ea3ng h\u1ecdc Spring, JVM tuning, backend chuy\xean s\xe2u <br/>"},{"id":"phan-tich-JVM","metadata":{"permalink":"/my-docusaurus/blog/phan-tich-JVM","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2026-02-22-phan-tich-JVM.md","source":"@site/blog/2026-02-22-phan-tich-JVM.md","title":"Ph\xe2n t\xedch c\u01a1 ch\u1ebf ho\u1ea1t \u0111\u1ed9ng c\u1ee7a JVM qua \u0111o\u1ea1n code c\u1ee5 th\u1ec3","description":"Trong b\xe0i vi\u1ebft n\xe0y, ch\xfang ta s\u1ebd ph\xe2n t\xedch to\xe0n b\u1ed9 c\u01a1 ch\u1ebf ho\u1ea1t \u0111\u1ed9ng c\u1ee7a JVM khi th\u1ef1c thi \u0111o\u1ea1n code sau:","date":"2026-02-22T00:00:00.000Z","tags":[{"inline":true,"label":"java","permalink":"/my-docusaurus/blog/tags/java"},{"inline":true,"label":"jvm","permalink":"/my-docusaurus/blog/tags/jvm"},{"inline":true,"label":"classloader","permalink":"/my-docusaurus/blog/tags/classloader"},{"inline":true,"label":"runtime-data-areas","permalink":"/my-docusaurus/blog/tags/runtime-data-areas"},{"inline":true,"label":"bytecode","permalink":"/my-docusaurus/blog/tags/bytecode"},{"inline":true,"label":"execution-engine","permalink":"/my-docusaurus/blog/tags/execution-engine"}],"readingTime":3.33,"hasTruncateMarker":false,"authors":[{"name":"Mai Duc Anh","title":"Blogger & Developer","url":"https://github.com/maiducanha1anh","imageURL":"https://github.com/yourusername.png","key":"admin","page":null}],"frontMatter":{"slug":"phan-tich-JVM","title":"Ph\xe2n t\xedch c\u01a1 ch\u1ebf ho\u1ea1t \u0111\u1ed9ng c\u1ee7a JVM qua \u0111o\u1ea1n code c\u1ee5 th\u1ec3","authors":["admin"],"tags":["java","jvm","classloader","runtime-data-areas","bytecode","execution-engine"]},"unlisted":false,"prevItem":{"title":"T\xecm hi\u1ec3u Java Platform \u2013 Execution Flow & JVM Architecture","permalink":"/my-docusaurus/blog/tim-hieu-Java-platform"},"nextItem":{"title":"T\xecm hi\u1ec3u v\u1ec1 ng\xf4n ng\u1eef Python \u2013 T\u1eeb t\u1ed5ng quan \u0111\u1ebfn c\u01a1 ch\u1ebf ho\u1ea1t \u0111\u1ed9ng b\xean trong","permalink":"/my-docusaurus/blog/tim-hieu-python"}},"content":"Trong b\xe0i vi\u1ebft n\xe0y, ch\xfang ta s\u1ebd ph\xe2n t\xedch to\xe0n b\u1ed9 c\u01a1 ch\u1ebf ho\u1ea1t \u0111\u1ed9ng c\u1ee7a JVM khi th\u1ef1c thi \u0111o\u1ea1n code sau:\\r\\n\\r\\n```java\\r\\nclass Student {\\r\\n    int age;\\r\\n}\\r\\n\\r\\npublic class Main {\\r\\n    public static void main(String[] args) {\\r\\n        Student s1 = new Student();\\r\\n        s1.age = 20;\\r\\n\\r\\n        Student s2 = s1;\\r\\n        s2.age = 25;\\r\\n\\r\\n        int x = 10;\\r\\n        int y = x;\\r\\n\\r\\n        System.out.println(\\"s1.age = \\" + s1.age);\\r\\n        System.out.println(\\"s2.age = \\" + s2.age);\\r\\n        System.out.println(\\"x = \\" + x);\\r\\n        System.out.println(\\"y = \\" + y);\\r\\n    }\\r\\n}\\r\\n```\\r\\n\\r\\n## I. \u0110\u1ea6U V\xc0O V\xc0 \u0110\u1ea6U RA C\u1ee6A JVM ?\\r\\n\\r\\n\u0110\u1ea6U V\xc0O <br /> \\r\\nKhi ch\u1ea1y:\\r\\n``` bash\\r\\njava Main\\r\\n```\\r\\nJVM nh\u1eadn \u0111\u1ea7u v\xe0o l\xe0:\\r\\n- File Main.class\\r\\n- File Student.class\\r\\n- Bytecode b\xean trong c\xe1c file n\xe0y\\r\\n\\r\\n\u26a0\ufe0f L\u01b0u \xfd: JVM kh\xf4ng ch\u1ea1y source code .java, m\xe0 ch\u1ea1y bytecode trong .class.\\r\\n\\r\\n\u0110\u1ea6U RA <br />\\r\\n- Console output\\r\\n- Thay \u0111\u1ed5i tr\u1ea1ng th\xe1i b\u1ed9 nh\u1edb\\r\\n- Object \u0111\u01b0\u1ee3c t\u1ea1o trong Heap\\r\\n- Stack Frame \u0111\u01b0\u1ee3c push/pop\\r\\n\\r\\nConsole in ra:\\r\\n```bash\\r\\ns1.age = 25\\r\\ns2.age = 25\\r\\nx = 10\\r\\ny = 10\\r\\n```\\r\\n\\r\\n\\r\\n## II. CLASS LOADER SUBSYSTEM\\r\\n1, Loading\\r\\n\\r\\nApplication ClassLoader load:\\r\\n\\r\\n- Main.class\\r\\n- Student.class\\r\\n- Metadata c\u1ee7a c\xe1c class \u0111\u01b0\u1ee3c \u0111\u01b0a v\xe0o Method Area (Metaspace).\\r\\n\\r\\n2, Linking\\r\\n\\r\\nG\u1ed3m 3 b\u01b0\u1edbc:\\r\\n\\r\\n\u2714 Verify\\r\\n\\r\\n- Ki\u1ec3m tra bytecode c\xf3 h\u1ee3p l\u1ec7 kh\xf4ng\\r\\n- Kh\xf4ng tr\xe0n stack\\r\\n- Kh\xf4ng truy c\u1eadp sai ki\u1ec3u d\u1eef li\u1ec7u\\r\\n\\r\\n\u2714 Prepare\\r\\n\\r\\n- C\u1ea5p ph\xe1t b\u1ed9 nh\u1edb cho static field (n\u1ebfu c\xf3)\\r\\n- G\xe1n gi\xe1 tr\u1ecb m\u1eb7c \u0111\u1ecbnh\\r\\n\\r\\n\u2714 Resolve\\r\\n\\r\\n- Chuy\u1ec3n symbolic reference \u2192 direct reference\\r\\n3, Initialization\\r\\n\\r\\n- Ch\u1ea1y static block (n\u1ebfu c\xf3)\\r\\n- Kh\u1edfi t\u1ea1o static variable\\r\\n\\r\\nSau giai \u0111o\u1ea1n n\xe0y\\r\\n\\r\\nTrong Method Area c\xf3:\\r\\n```bash\\r\\nClass Student\\r\\n  field: age\\r\\n  constructor\\r\\n\\r\\nClass Main\\r\\n  method: main()\\r\\n  bytecode\\r\\n  constant pool\\r\\n  ```\\r\\n\\r\\n\u26a0\ufe0f Ch\u01b0a c\xf3 object n\xe0o trong Heap.\\r\\n\\r\\n## III. 16 B\u01af\u1edaC RUNTIME THEO JAVA VISUALIZER\\r\\n\\r\\nSTEP 1 \u2014 T\u1ea1o Main Thread\\r\\n\\r\\nJVM t\u1ea1o:\\r\\n\\r\\n- Main Thread\\r\\n- Stack cho thread\\r\\n- Frame main()\\r\\n\\r\\n```bash\\r\\nStack\\r\\n\u2514\u2500\u2500 Frame: main()\\r\\n     args \u2192 String[]\\r\\n```\\r\\nHeap: r\u1ed7ng\\r\\n\\r\\n---\\r\\n\\r\\nSTEP 2 \u2014 new Student()\\r\\n\\r\\nBytecode:\\r\\n```bash\\r\\nnew\\r\\ndup\\r\\ninvokespecial\\r\\nastore\\r\\n```\\r\\n\u0110i\u1ec1u x\u1ea3y ra:\\r\\n\\r\\n- C\u1ea5p ph\xe1t object trong Heap\\r\\n- age = 0 (default)\\r\\n- Reference \u0111\u01b0\u1ee3c push l\xean Operand Stack\\r\\n\\r\\nHeap:\\r\\n```bash\\r\\nStudent instance\\r\\n age = 0\\r\\n ```\\r\\n\\r\\n ---\\r\\n\\r\\nSTEP 3 \u2014 G\u1ecdi constructor\\r\\n\\r\\ninvokespecial g\u1ecdi `<init>`\\r\\n\\r\\nJVM t\u1ea1o Frame m\u1edbi:\\r\\n```bash\\r\\nStack\\r\\n\u2514\u2500\u2500 Frame `<init>`\\r\\n\u2514\u2500\u2500 Frame main\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\nSTEP 4 \u2014 Constructor return\\r\\n\\r\\nFrame `<init>` b\u1ecb pop.\\r\\n\\r\\n---\\r\\n\\r\\nSTEP 5 \u2014 G\xe1n cho s1\\r\\n\\r\\nReference l\u01b0u v\xe0o Local Variable Array index 1.\\r\\n```bash\\r\\nFrame main:\\r\\n s1 \u2192 Student instance\\r\\n ```\\r\\n\\r\\n---\\r\\n\\r\\nSTEP 6 \u2014 s1.age = 20\\r\\n\\r\\nExecution Engine:\\r\\n\\r\\naload_1\\r\\n\\r\\nbipush 20\\r\\n\\r\\nputfield\\r\\n\\r\\nHeap:\\r\\n```bash\\r\\nStudent\\r\\n age = 20\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\nSTEP 7 \u2014 Student s2 = s1\\r\\n\\r\\nCopy reference.\\r\\n```bash\\r\\ns1 \u2500\u2500\u2510\\r\\n     \u2502\\r\\ns2 \u2500\u2500\u2518\\r\\n```\\r\\nKh\xf4ng t\u1ea1o object m\u1edbi\\r\\n\\r\\n---\\r\\n\\r\\nSTEP 8 \u2014 s2.age = 25\\r\\n\\r\\nputfield ghi \u0111\xe8 Heap.\\r\\n```bash\\r\\nStudent\\r\\n age = 25\\r\\n ```\\r\\n\\r\\n---\\r\\n\\r\\nSTEP 9 - int x = 10\\r\\nPrimitive l\u01b0u tr\u1ef1c ti\u1ebfp trong Stack Frame.\\r\\n```bash\\r\\nx = 10\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\nSTEP 10 \u2014 int y = x\\r\\n\\r\\nCopy value.\\r\\n```bash\\r\\nx = 10\\r\\ny = 10\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\nSTEP 11 \u2014 Chu\u1ea9n b\u1ecb println \u0111\u1ea7u ti\xean\\r\\n\\r\\nBi\u1ec3u th\u1ee9c:\\r\\n```bash \\r\\n\\"s1.age = \\" + s1.age\\r\\n```\\r\\nJVM:\\r\\n\\r\\n- L\u1ea5y 25 t\u1eeb Heap\\r\\n- T\u1ea1o String m\u1edbi trong Heap\\r\\n\\r\\n---\\r\\n\\r\\nSTEP 12 \u2014 G\u1ecdi println()\\r\\n\\r\\nFrame m\u1edbi \u0111\u01b0\u1ee3c push:\\r\\n```bash\\r\\nFrame println()\\r\\nFrame main()\\r\\n```\\r\\nSau khi in \u2192 pop.\\r\\n\\r\\n---\\r\\n\\r\\nSTEP 13 \u2014 println th\u1ee9 2\\r\\n\\r\\nT\u1ea1o String m\u1edbi \u2192 push frame \u2192 pop.\\r\\n\\r\\n---\\r\\n\\r\\nSTEP 14 \u2014 println x\\r\\n\\r\\nPush frame \u2192 pop.\\r\\n\\r\\n---\\r\\n\\r\\nSTEP 15 \u2014 println y\\r\\n\\r\\nPush frame \u2192 pop.\\r\\n\\r\\n---\\r\\n\\r\\nSTEP 16 \u2014 main() k\u1ebft th\xfac\\r\\n\\r\\nFrame main b\u1ecb pop.\\r\\n\\r\\nStack r\u1ed7ng.\\r\\n\\r\\nObject trong Heap kh\xf4ng c\xf2n reference.\\r\\n\\r\\n- Garbage Collector s\u1ebd d\u1ecdn sau.\\r\\n\\r\\n---\\r\\n\\r\\n## IV. T\u1ed4NG K\u1ebeT B\u1ed8 NH\u1eda\\r\\n\\r\\n| Th\xe0nh ph\u1ea7n    | L\u01b0u g\xec                              |\\r\\n|---------------|-------------------------------------|\\r\\n| Method Area   | Metadata, bytecode, constant pool   |\\r\\n| Heap          | Object                              |\\r\\n| Stack         | Primitive + Reference               |\\r\\n| PC Register   | V\u1ecb tr\xed bytecode hi\u1ec7n t\u1ea1i            |\\r\\n\\r\\n\\r\\n## V. K\u1ebft lu\u1eadn \\r\\n\\r\\nTham kh\u1ea3o slide chi ti\u1ebft t\u1ea1i \u0111\xe2y :\\r\\n- \ud83d\udd17 https://www.canva.com/design/DAHBYC9gqew/Qj0cc0miT3og0gFKV8UZJw/edit\\r\\n\\r\\nC\u1ed1t l\xf5i c\u1ea7n n\u1eafm :\\r\\n- Object lu\xf4n n\u1eb1m trong Heap\\r\\n- Reference n\u1eb1m trong Stack\\r\\n- Primitive n\u1eb1m trong Stack\\r\\n- Method call \u2192 t\u1ea1o Stack Frame\\r\\n- Constant Pool l\u01b0u symbolic reference\\r\\n- Execution Engine \u0111\u1ecdc bytecode\\r\\n- GC d\u1ecdn object khi kh\xf4ng c\xf2n reference\\r\\n\\r\\nQua v\xed d\u1ee5 \u0111\u01a1n gi\u1ea3n n\xe0y, ta th\u1ea5y:\\r\\n\\r\\nJVM kh\xf4ng ch\u1ec9 \u201cch\u1ea1y code\u201d, m\xe0:\\r\\n- Load class\\r\\n- X\xe1c minh bytecode\\r\\n- Qu\u1ea3n l\xfd b\u1ed9 nh\u1edb\\r\\n- Th\u1ef1c thi theo ki\u1ebfn tr\xfac stack\\r\\n- G\u1ecdi native code\\r\\n- Thu gom r\xe1c t\u1ef1 \u0111\u1ed9ng\\r\\n\\r\\n\\r\\nHi\u1ec3u r\xf5 c\u01a1 ch\u1ebf n\xe0y gi\xfap ta:\\r\\n- Tr\xe1nh memory leak\\r\\n- Hi\u1ec3u reference vs primitive\\r\\n- Hi\u1ec3u v\xec sao GC ho\u1ea1t \u0111\u1ed9ng\\r\\n- Debug v\u1ea5n \u0111\u1ec1 li\xean quan t\u1edbi JVM s\xe2u h\u01a1n"},{"id":"tim-hieu-python","metadata":{"permalink":"/my-docusaurus/blog/tim-hieu-python","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2026-02-02-tim-hieu-ve-Python.md","source":"@site/blog/2026-02-02-tim-hieu-ve-Python.md","title":"T\xecm hi\u1ec3u v\u1ec1 ng\xf4n ng\u1eef Python \u2013 T\u1eeb t\u1ed5ng quan \u0111\u1ebfn c\u01a1 ch\u1ebf ho\u1ea1t \u0111\u1ed9ng b\xean trong","description":"1. T\xecm hi\u1ec3u chung v\u1ec1 ng\xf4n ng\u1eef Python","date":"2026-02-02T00:00:00.000Z","tags":[{"inline":true,"label":"python","permalink":"/my-docusaurus/blog/tags/python"},{"inline":true,"label":"interpreted","permalink":"/my-docusaurus/blog/tags/interpreted"},{"inline":true,"label":"compiled","permalink":"/my-docusaurus/blog/tags/compiled"},{"inline":true,"label":"cpython","permalink":"/my-docusaurus/blog/tags/cpython"},{"inline":true,"label":"memory-management","permalink":"/my-docusaurus/blog/tags/memory-management"}],"readingTime":5.74,"hasTruncateMarker":false,"authors":[{"name":"Mai Duc Anh","title":"Blogger & Developer","url":"https://github.com/maiducanha1anh","imageURL":"https://github.com/yourusername.png","key":"admin","page":null}],"frontMatter":{"slug":"tim-hieu-python","sidebar_position":1,"title":"T\xecm hi\u1ec3u v\u1ec1 ng\xf4n ng\u1eef Python \u2013 T\u1eeb t\u1ed5ng quan \u0111\u1ebfn c\u01a1 ch\u1ebf ho\u1ea1t \u0111\u1ed9ng b\xean trong","authors":["admin"],"tags":["python","interpreted","compiled","cpython","memory-management"]},"unlisted":false,"prevItem":{"title":"Ph\xe2n t\xedch c\u01a1 ch\u1ebf ho\u1ea1t \u0111\u1ed9ng c\u1ee7a JVM qua \u0111o\u1ea1n code c\u1ee5 th\u1ec3","permalink":"/my-docusaurus/blog/phan-tich-JVM"},"nextItem":{"title":"H\u01b0\u1edbng d\u1eabn t\u1ea1o Blog c\xe1 nh\xe2n b\u1eb1ng Docusaurus","permalink":"/my-docusaurus/blog/bai-viet-dau-tien"}},"content":"## 1. T\xecm hi\u1ec3u chung v\u1ec1 ng\xf4n ng\u1eef Python\\r\\n\\r\\nPython l\xe0 m\u1ed9t ng\xf4n ng\u1eef l\u1eadp tr\xecnh b\u1eadc cao (high-level language), \u0111\u01b0\u1ee3c t\u1ea1o ra b\u1edfi **Guido van Rossum** v\xe0 ch\xednh th\u1ee9c ra m\u1eaft l\u1ea7n \u0111\u1ea7u v\xe0o n\u0103m **1991**. Python \u0111\u01b0\u1ee3c thi\u1ebft k\u1ebf v\u1edbi tri\u1ebft l\xfd **\u0111\u01a1n gi\u1ea3n \u2013 d\u1ec5 \u0111\u1ecdc \u2013 d\u1ec5 h\u1ecdc \u2013 d\u1ec5 b\u1ea3o tr\xec**, gi\xfap l\u1eadp tr\xecnh vi\xean t\u1eadp trung nhi\u1ec1u h\u01a1n v\xe0o logic nghi\u1ec7p v\u1ee5 thay v\xec c\xfa ph\xe1p ph\u1ee9c t\u1ea1p.\\r\\n\\r\\n### \u0110\u1eb7c \u0111i\u1ec3m n\u1ed5i b\u1eadt c\u1ee7a Python\\r\\n\\r\\n- C\xfa ph\xe1p g\u1ea7n v\u1edbi ng\xf4n ng\u1eef t\u1ef1 nhi\xean, d\u1ec5 \u0111\u1ecdc\\r\\n- Ng\xf4n ng\u1eef **\u0111a m\u1ee5c \u0111\xedch**: Web, AI, Data Science, Automation, Game, IoT\\r\\n- H\u1ec7 sinh th\xe1i th\u01b0 vi\u1ec7n phong ph\xfa (NumPy, Pandas, TensorFlow, Django, Flask, ...)\\r\\n- Ch\u1ea1y \u0111a n\u1ec1n t\u1ea3ng: Windows, Linux, macOS\\r\\n- C\u1ed9ng \u0111\u1ed3ng l\u1edbn, t\xe0i li\u1ec7u \u0111\u1ea7y \u0111\u1ee7\\r\\n\\r\\nPython \u0111\u1eb7c bi\u1ec7t ph\xf9 h\u1ee3p cho:\\r\\n- Sinh vi\xean IT\\r\\n- Ng\u01b0\u1eddi m\u1edbi h\u1ecdc l\u1eadp tr\xecnh\\r\\n- C\xe1c h\u1ec7 th\u1ed1ng c\u1ea7n ph\xe1t tri\u1ec3n nhanh (Rapid Development)\\r\\n\\r\\n---\\r\\n\\r\\n## 2. Interpreted vs Compiled \u2013 C\u01a1 ch\u1ebf th\xf4ng d\u1ecbch v\xe0 bi\xean d\u1ecbch\\r\\n\\r\\nKhi n\xf3i \u0111\u1ebfn c\xe1ch m\u1ed9t ng\xf4n ng\u1eef \u0111\u01b0\u1ee3c th\u1ef1c thi, ta th\u01b0\u1eddng ph\xe2n bi\u1ec7t hai kh\xe1i ni\u1ec7m: **Compiled** v\xe0 **Interpreted**.\\r\\n\\r\\n### Compiled Language (Ng\xf4n ng\u1eef bi\xean d\u1ecbch)\\r\\n\\r\\nV\xed d\u1ee5: C, C++, Go\\r\\n\\r\\n**Quy tr\xecnh:**\\r\\n\\r\\nSource Code (.c) <br />\\r\\n\u2193 <br />\\r\\nCompiler <br />\\r\\n\u2193 <br />\\r\\nMachine Code (.exe) <br />\\r\\n\\r\\n\\r\\n\u0110\u1eb7c \u0111i\u1ec3m:\\r\\n- Bi\xean d\u1ecbch **to\xe0n b\u1ed9** ch\u01b0\u01a1ng tr\xecnh tr\u01b0\u1edbc khi ch\u1ea1y\\r\\n- Ch\u1ea1y nhanh, hi\u1ec7u n\u0103ng cao\\r\\n- Ph\u1ee5 thu\u1ed9c h\u1ec7 \u0111i\u1ec1u h\xe0nh v\xe0 ki\u1ebfn tr\xfac CPU\\r\\n- Kh\xf3 debug h\u01a1n\\r\\n\\r\\n---\\r\\n\\r\\n### Interpreted Language (Ng\xf4n ng\u1eef th\xf4ng d\u1ecbch)\\r\\n\\r\\nV\xed d\u1ee5: Python, JavaScript, PHP\\r\\n\\r\\nQuy tr\xecnh:\\r\\n\\r\\nSource Code (.py) <br />\\r\\n\u2193 <br />\\r\\nInterpreter <br />\\r\\n\u2193 <br />\\r\\nTh\u1ef1c thi t\u1eebng d\xf2ng <br />\\r\\n\\r\\n\\r\\n\u0110\u1eb7c \u0111i\u1ec3m:\\r\\n- Kh\xf4ng c\u1ea7n t\u1ea1o file `.exe`\\r\\n- D\u1ec5 debug, d\u1ec5 h\u1ecdc\\r\\n- Th\u01b0\u1eddng ch\u1eadm h\u01a1n compiled language\\r\\n\\r\\n\u26a0\ufe0f **Python kh\xf4ng ho\xe0n to\xe0n l\xe0 interpreted thu\u1ea7n t\xfay** \u2013 \u0111i\u1ec1u n\xe0y s\u1ebd r\xf5 h\u01a1n khi t\xecm hi\u1ec3u CPython.\\r\\n\\r\\n---\\r\\n\\r\\n## 3. Workflow c\u1ee7a Python \u2013 T\u1eeb l\xfac g\xf5 code \u0111\u1ebfn khi ch\u01b0\u01a1ng tr\xecnh ch\u1ea1y\\r\\n\\r\\nKhi b\u1ea1n ch\u1ea1y m\u1ed9t file Python (`file.py`), Python kh\xf4ng th\u1ef1c thi tr\u1ef1c ti\u1ebfp source code ngay l\u1eadp t\u1ee9c.\\r\\n\\r\\n### Workflow t\u1ed5ng qu\xe1t\\r\\n\\r\\nIDE <br />\\r\\n \u2193 (Save) <br />\\r\\nfile.py (\u1ed4 c\u1ee9ng) <br />\\r\\n \u2193 (Run) <br />\\r\\nSource Code (RAM) <br />\\r\\n \u2193 <br />\\r\\nLexical Analysis \u2192 Tokens (RAM) <br />\\r\\n \u2193 <br />\\r\\nParsing \u2192 AST (RAM) <br />\\r\\n \u2193 <br />\\r\\nCompile <br />\\r\\n \u2193 <br />\\r\\nBytecode (RAM + c\xf3 th\u1ec3 ghi .pyc v\xe0o disk) <br />\\r\\n \u2193 <br />\\r\\nPython Virtual Machine (RAM) <br />\\r\\n \u2193 <br />\\r\\nCPU th\u1ef1c thi <br />\\r\\n\\r\\n\\r\\n### Ph\xe2n t\xedch chi ti\u1ebft\\r\\n\\r\\n**Giai \u0111o\u1ea1n 1: Python \u0111\u1ecdc file.py v\xe0o b\u1ed9 nh\u1edb**\\r\\n(Python Source Code \u2192 RAM)\\r\\n\\r\\nKhi b\u1ea1n ch\u1ea1y: \\r\\n\\r\\n```bash\\r\\npython main.py\\r\\n```\\r\\n\u0110\u1ea7u v\xe0o :\\r\\n- File.py\\r\\n- V\u1ecb tr\xed: \u1ed5 c\u1ee9ng \\r\\n\\r\\nPython l\xe0m g\xec?\\r\\n- H\u1ec7 \u0111i\u1ec1u h\xe0nh \u0111\u1ecdc n\u1ed9i dung file.py\\r\\n- N\u1ea1p to\xe0n b\u1ed9 source code v\xe0o RAM\\r\\n- Chuy\u1ec3n code sang d\u1ea1ng chu\u1ed7i k\xfd t\u1ef1 (text)\\r\\n\\r\\n\u0110\u1ea7u ra :\\r\\n- Source code Python n\u1eb1m trong RAM\\r\\n- File.py v\u1eabn c\xf2n tr\xean \u1ed5 c\u1ee9ng, kh\xf4ng b\u1ecb thay \u0111\u1ed5i\\r\\n\\r\\n\ud83d\udccc T\u1eeb th\u1eddi \u0111i\u1ec3m n\xe0y:\\r\\n\\r\\nPython ch\u1ec9 l\xe0m vi\u1ec7c v\u1edbi code trong RAM\\r\\n\\r\\n\u1ed4 c\u1ee9ng ch\u1ec9 c\xf2n vai tr\xf2 l\u01b0u tr\u1eef\\r\\n\\r\\n---\\r\\n\\r\\n**Giai \u0111o\u1ea1n 2: Lexical Analysis & Parsing**\\r\\n(Source Code \u2192 AST)\\r\\n\\r\\n2.1 Lexical Analysis (Ph\xe2n t\xedch t\u1eeb v\u1ef1ng)\\r\\n\\r\\n\u0110\u1ea7u v\xe0o :\\r\\n- Source code (text) trong RAM\\r\\nV\xed d\u1ee5 :\\r\\n```bash\\r\\na = 10\\r\\n```\\r\\nPython l\xe0m g\xec?\\r\\n\\r\\nChia code th\xe0nh c\xe1c token\\r\\n\\r\\na \u2192 IDENTIFIER\\r\\n\\r\\n= \u2192 OPERATOR\\r\\n\\r\\n10 \u2192 NUMBER\\r\\n\\r\\n\ud83d\udccc L\xfac n\xe0y:\\r\\n\\r\\nPython ch\u01b0a hi\u1ec3u logic\\r\\n\\r\\nCh\u1ec9 m\u1edbi hi\u1ec3u \u201ck\xfd hi\u1ec7u\u201d\\r\\n\\r\\n2.2 Parsing (Ph\xe2n t\xedch c\xfa ph\xe1p)\\r\\n\\r\\n\u0110\u1ea7u v\xe0o :\\r\\n- Token stream (RAM)\\r\\n\\r\\nPython l\xe0m g\xec?\\r\\n- Ki\u1ec3m tra c\xfa ph\xe1p c\xf3 h\u1ee3p l\u1ec7 kh\xf4ng\\r\\n- X\xe2y d\u1ef1ng Abstract Syntax Tree (AST)\\r\\n\\r\\nV\xed d\u1ee5:\\r\\n```bash\\r\\na = 10\\r\\n```\\r\\n\\r\\n\u2192 AST bi\u1ec3u di\u1ec5n:\\r\\n\\r\\n- G\xe1n gi\xe1 tr\u1ecb 10 cho bi\u1ebfn a\\r\\n\\r\\n\u0110\u1ea7u ra :\\r\\n- AST\\r\\n- N\u1eb1m trong RAM\\r\\n\\r\\n\u274c N\u1ebfu sai c\xfa ph\xe1p \u2192 SyntaxError (d\u1eebng t\u1ea1i \u0111\xe2y)\\r\\n\\r\\n---\\r\\n\\r\\n**Giai \u0111o\u1ea1n 3: Compile sang Bytecode**\\r\\n(AST \u2192 Bytecode .pyc)\\r\\n\\r\\n\u0110\u1ea7u v\xe0o :\\r\\n- AST (RAM)\\r\\n\\r\\nPython l\xe0m g\xec?\\r\\n\\r\\n- Bi\xean d\u1ecbch AST th\xe0nh Bytecode\\r\\n\\r\\nBytecode l\xe0:\\r\\n\\r\\n- M\xe3 trung gian\\r\\n\\r\\n- Kh\xf4ng ph\u1ea3i m\xe3 m\xe1y\\r\\n\\r\\n- Kh\xf4ng ph\u1ee5 thu\u1ed9c h\u1ec7 \u0111i\u1ec1u h\xe0nh\\r\\n\\r\\n\u0110\u1ea7u ra :\\r\\n\\r\\n- Bytecode\\r\\n\\r\\n- N\u1eb1m trong RAM\\r\\n\\r\\n\u0110\u1ed3ng th\u1eddi:\\r\\n\\r\\n- Python c\xf3 th\u1ec3 ghi bytecode ra \u1ed5 c\u1ee9ng\\r\\n\\r\\n- D\u01b0\u1edbi d\u1ea1ng file .pyc trong th\u01b0 m\u1ee5c __pycache__\\r\\n\\r\\n\ud83d\udccc Quan tr\u1ecdng:\\r\\n\\r\\n.pyc kh\xf4ng ph\u1ea3i l\xfac n\xe0o c\u0169ng \u0111\u01b0\u1ee3c t\u1ea1o\\r\\n\\r\\nD\xf9ng \u0111\u1ec3:\\r\\n\\r\\n- Ch\u1ea1y nhanh h\u01a1n \u1edf l\u1ea7n sau\\r\\n\\r\\n- Tr\xe1nh compile l\u1ea1i n\u1ebfu code kh\xf4ng \u0111\u1ed5i\\r\\n\\r\\n---\\r\\n\\r\\n**Giai \u0111o\u1ea1n 4: Python Virtual Machine (PVM)**\\r\\n(Bytecode \u2192 Th\u1ef1c thi)\\r\\n\u0110\u1ea7u v\xe0o :\\r\\n- Bytecode (RAM)\\r\\n\\r\\nPython l\xe0m g\xec?\\r\\n\\r\\n+ Python Virtual Machine:\\r\\n\\r\\n-\u0110\u1ecdc t\u1eebng instruction trong bytecode\\r\\n\\r\\n-Th\u1ef1c thi l\u1ea7n l\u01b0\u1ee3t\\r\\n\\r\\n+ M\u1ed7i instruction:\\r\\n\\r\\n- G\u1ecdi h\xe0m C t\u01b0\u01a1ng \u1ee9ng trong CPython\\r\\n\\r\\n- CPU th\u1ef1c hi\u1ec7n l\u1ec7nh th\u1eadt\\r\\n\\r\\n\u0110\u1ea7u ra :\\r\\n\\r\\n- Ch\u01b0\u01a1ng tr\xecnh ch\u1ea1y\\r\\n\\r\\n- T\u1ea1o bi\u1ebfn, object trong heap\\r\\n\\r\\n- In ra m\xe0n h\xecnh, ghi file, g\u1ecdi API, \u2026\\r\\n\\r\\n\ud83d\udccc L\u01b0u \xfd c\u1ef1c quan tr\u1ecdng:\\r\\n\\r\\n- PVM ch\u1ea1y trong RAM\\r\\n\\r\\n- CPU kh\xf4ng ch\u1ea1y source code Python\\r\\n\\r\\n- CPU ch\u1ec9 ch\u1ea1y m\xe3 m\xe1y c\u1ee7a CPython\\r\\n\\r\\n\u27a1\ufe0f V\xec v\u1eady Python th\u01b0\u1eddng \u0111\u01b0\u1ee3c m\xf4 t\u1ea3 l\xe0:\\r\\n\\r\\n> **\u201cInterpreted language with a compilation step\u201d**\\r\\n\\r\\n---\\r\\n\\r\\n## 4. CPython l\xe0 g\xec? V\xec sao n\xf3 quan tr\u1ecdng?\\r\\n\\r\\n### CPython\\r\\n\\r\\nCPython l\xe0 **implementation ph\u1ed5 bi\u1ebfn nh\u1ea5t c\u1ee7a Python**, \u0111\u01b0\u1ee3c vi\u1ebft b\u1eb1ng ng\xf4n ng\u1eef **C**.\\r\\n\\r\\n\ud83d\udc49 Khi b\u1ea1n t\u1ea3i Python t\u1eeb `python.org`, b\u1ea1n \u0111ang s\u1eed d\u1ee5ng **CPython**.\\r\\n\\r\\n### Vai tr\xf2 c\u1ee7a CPython\\r\\n\\r\\n- Bi\xean d\u1ecbch Python code \u2192 Bytecode\\r\\n- Th\u1ef1c thi bytecode th\xf4ng qua PVM\\r\\n- Qu\u1ea3n l\xfd b\u1ed9 nh\u1edb\\r\\n- Cung c\u1ea5p API cho C Extension\\r\\n\\r\\n### C\xe1c implementation kh\xe1c c\u1ee7a Python\\r\\n\\r\\n- **PyPy**: s\u1eed d\u1ee5ng JIT, c\xf3 th\u1ec3 nhanh h\u01a1n CPython\\r\\n- **Jython**: ch\u1ea1y tr\xean JVM\\r\\n- **IronPython**: ch\u1ea1y tr\xean .NET\\r\\n\\r\\n\u27a1\ufe0f Tuy nhi\xean, **CPython v\u1eabn l\xe0 ti\xeau chu\u1ea9n m\u1eb7c \u0111\u1ecbnh**.\\r\\n\\r\\n---\\r\\n\\r\\n## 5. Python qu\u1ea3n l\xfd b\u1ed9 nh\u1edb nh\u01b0 th\u1ebf n\xe0o?\\r\\n\\r\\nPython **t\u1ef1 \u0111\u1ed9ng qu\u1ea3n l\xfd b\u1ed9 nh\u1edb**, l\u1eadp tr\xecnh vi\xean kh\xf4ng c\u1ea7n c\u1ea5p ph\xe1t hay gi\u1ea3i ph\xf3ng th\u1ee7 c\xf4ng.\\r\\n\\r\\n### C\xe1c v\xf9ng b\u1ed9 nh\u1edb ch\xednh\\r\\n\\r\\n1. **Stack Memory**\\r\\n   - L\u01b0u bi\u1ebfn c\u1ee5c b\u1ed9\\r\\n   - Function call\\r\\n\\r\\n2. **Heap Memory**\\r\\n   - L\u01b0u object (list, dict, class instance, \u2026)\\r\\n   - Do CPython qu\u1ea3n l\xfd\\r\\n\\r\\n### Object trong Python g\u1ed3m\\r\\n\\r\\n- Gi\xe1 tr\u1ecb (value)\\r\\n- Ki\u1ec3u d\u1eef li\u1ec7u (type)\\r\\n- Reference count (s\u1ed1 l\u01b0\u1ee3ng tham chi\u1ebfu)\\r\\n\\r\\n---\\r\\n\\r\\n## 6. Garbage Collection trong Python\\r\\n\\r\\n### Reference Counting\\r\\n\\r\\nPython s\u1eed d\u1ee5ng **reference counting** l\xe0m c\u01a1 ch\u1ebf ch\xednh.\\r\\n\\r\\n- M\u1ed7i object c\xf3 s\u1ed1 l\u01b0\u1ee3ng reference\\r\\n- Khi reference = 0 \u2192 object b\u1ecb gi\u1ea3i ph\xf3ng\\r\\n\\r\\nV\xed d\u1ee5:\\r\\n\\r\\n```python\\r\\na = []\\r\\nb = a\\r\\n\\r\\ndel a\\r\\ndel b  # l\xfac n\xe0y object list m\u1edbi b\u1ecb gi\u1ea3i ph\xf3ng\\r\\n```\\r\\n\\r\\n## 7. T\u1ed5ng k\u1ebft\\r\\n\\r\\nTham kh\u1ea3o slide chi ti\u1ebft t\u1ea1i \u0111\xe2y :\\r\\n- \ud83d\udd17 https://www.canva.com/design/DAG_3zWkweQ/ZLs9aa_VVotSC-yXgsAZOw/edit\\r\\n\\r\\nPython l\xe0 ng\xf4n ng\u1eef c\xf3 c\xfa ph\xe1p \u0111\u01a1n gi\u1ea3n, d\u1ec5 h\u1ecdc, nh\u01b0ng **b\xean trong c\xf3 c\u01a1 ch\u1ebf ho\u1ea1t \u0111\u1ed9ng t\u01b0\u01a1ng \u0111\u1ed1i ph\u1ee9c t\u1ea1p**. Khi ch\u1ea1y m\u1ed9t ch\u01b0\u01a1ng tr\xecnh Python, source code kh\xf4ng \u0111\u01b0\u1ee3c th\u1ef1c thi tr\u1ef1c ti\u1ebfp m\xe0 ph\u1ea3i tr\u1ea3i qua nhi\u1ec1u giai \u0111o\u1ea1n nh\u01b0 ph\xe2n t\xedch c\xfa ph\xe1p, bi\xean d\u1ecbch sang bytecode v\xe0 th\u1ef1c thi th\xf4ng qua **Python Virtual Machine (PVM)**.\\r\\n\\r\\nPython kh\xf4ng ph\u1ea3i l\xe0 interpreted thu\u1ea7n t\xfay, m\xe0 l\xe0 **ng\xf4n ng\u1eef th\xf4ng d\u1ecbch c\xf3 b\u01b0\u1edbc bi\xean d\u1ecbch trung gian**. **CPython** gi\u1eef vai tr\xf2 trung t\xe2m trong vi\u1ec7c bi\xean d\u1ecbch, th\u1ef1c thi v\xe0 qu\u1ea3n l\xfd b\u1ed9 nh\u1edb. Nh\u1edd c\u01a1 ch\u1ebf **qu\u1ea3n l\xfd b\u1ed9 nh\u1edb t\u1ef1 \u0111\u1ed9ng v\xe0 Garbage Collection**, Python gi\xfap l\u1eadp tr\xecnh vi\xean t\u1eadp trung v\xe0o logic thay v\xec x\u1eed l\xfd t\xe0i nguy\xean.\\r\\n\\r\\nVi\u1ec7c hi\u1ec3u r\xf5 workflow v\xe0 c\u01a1 ch\u1ebf b\xean trong c\u1ee7a Python gi\xfap l\u1eadp tr\xecnh vi\xean vi\u1ebft code hi\u1ec7u qu\u1ea3 h\u01a1n, debug t\u1ed1t h\u01a1n v\xe0 c\xf3 n\u1ec1n t\u1ea3ng \u0111\u1ec3 h\u1ecdc s\xe2u v\u1ec1 Python trong c\xe1c h\u1ec7 th\u1ed1ng l\u1edbn."},{"id":"bai-viet-dau-tien","metadata":{"permalink":"/my-docusaurus/blog/bai-viet-dau-tien","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2026-01-22-huong-dan-docusaurus.md","source":"@site/blog/2026-01-22-huong-dan-docusaurus.md","title":"H\u01b0\u1edbng d\u1eabn t\u1ea1o Blog c\xe1 nh\xe2n b\u1eb1ng Docusaurus","description":"Trong b\xe0i vi\u1ebft n\xe0y, m\xecnh s\u1ebd h\u01b0\u1edbng d\u1eabn chi ti\u1ebft c\xe1ch t\u1ea1o m\u1ed9t blog c\xe1 nh\xe2n b\u1eb1ng Docusaurus \u2013 m\u1ed9t c\xf4ng c\u1ee5 r\u1ea5t m\u1ea1nh \u0111\u1ec3 x\xe2y d\u1ef1ng website t\xe0i li\u1ec7u v\xe0 blog t\u0129nh.","date":"2026-01-22T00:00:00.000Z","tags":[{"inline":false,"label":"Docusaurus","permalink":"/my-docusaurus/blog/tags/docusaurus","description":"Docusaurus tag description"},{"inline":true,"label":"blog","permalink":"/my-docusaurus/blog/tags/blog"},{"inline":true,"label":"huong-dan","permalink":"/my-docusaurus/blog/tags/huong-dan"},{"inline":true,"label":"lap-trinh","permalink":"/my-docusaurus/blog/tags/lap-trinh"}],"readingTime":1.07,"hasTruncateMarker":false,"authors":[{"name":"Mai Duc Anh","title":"Blogger & Developer","url":"https://github.com/maiducanha1anh","imageURL":"https://github.com/yourusername.png","key":"admin","page":null}],"frontMatter":{"slug":"bai-viet-dau-tien","title":"H\u01b0\u1edbng d\u1eabn t\u1ea1o Blog c\xe1 nh\xe2n b\u1eb1ng Docusaurus","authors":["admin"],"tags":["docusaurus","blog","huong-dan","lap-trinh"]},"unlisted":false,"prevItem":{"title":"T\xecm hi\u1ec3u v\u1ec1 ng\xf4n ng\u1eef Python \u2013 T\u1eeb t\u1ed5ng quan \u0111\u1ebfn c\u01a1 ch\u1ebf ho\u1ea1t \u0111\u1ed9ng b\xean trong","permalink":"/my-docusaurus/blog/tim-hieu-python"}},"content":"Trong b\xe0i vi\u1ebft n\xe0y, m\xecnh s\u1ebd h\u01b0\u1edbng d\u1eabn chi ti\u1ebft c\xe1ch t\u1ea1o m\u1ed9t blog c\xe1 nh\xe2n b\u1eb1ng **Docusaurus** \u2013 m\u1ed9t c\xf4ng c\u1ee5 r\u1ea5t m\u1ea1nh \u0111\u1ec3 x\xe2y d\u1ef1ng website t\xe0i li\u1ec7u v\xe0 blog t\u0129nh.\\r\\n\\r\\nB\xe0i vi\u1ebft ph\xf9 h\u1ee3p cho:\\r\\n- Sinh vi\xean IT  \\r\\n- Ng\u01b0\u1eddi m\u1edbi h\u1ecdc web  \\r\\n- Ng\u01b0\u1eddi mu\u1ed1n c\xf3 blog c\xe1 nh\xe2n chuy\xean nghi\u1ec7p  \\r\\n\\r\\n---\\r\\n\\r\\n## 1. Docusaurus l\xe0 g\xec?\\r\\n\\r\\nDocusaurus l\xe0 m\u1ed9t framework m\xe3 ngu\u1ed3n m\u1edf do Facebook ph\xe1t tri\u1ec3n, d\xf9ng \u0111\u1ec3 t\u1ea1o:\\r\\n- Blog c\xe1 nh\xe2n  \\r\\n- Website t\xe0i li\u1ec7u  \\r\\n- Website gi\u1edbi thi\u1ec7u d\u1ef1 \xe1n  \\r\\n\\r\\n\u01afu \u0111i\u1ec3m:\\r\\n- Mi\u1ec5n ph\xed  \\r\\n- D\u1ec5 d\xf9ng  \\r\\n- Vi\u1ebft b\xe0i b\u1eb1ng Markdown  \\r\\n- Deploy d\u1ec5 l\xean GitHub Pages  \\r\\n\\r\\n---\\r\\n\\r\\n## 2. Chu\u1ea9n b\u1ecb m\xf4i tr\u01b0\u1eddng\\r\\n\\r\\nB\u1ea1n c\u1ea7n c\xe0i s\u1eb5n:\\r\\n\\r\\n- Node.js (phi\xean b\u1ea3n >= 18)\\r\\n- npm (\u0111i k\xe8m Node.js)\\r\\n\\r\\nKi\u1ec3m tra b\u1eb1ng l\u1ec7nh:\\r\\n\\r\\n```bash\\r\\nnode -v\\r\\nnpm -v\\r\\n```\\r\\n---\\r\\n## 3.C\xe1c b\u01b0\u1edbc t\u1ea1o Blog v\u1edbi Docusaurus\\r\\n\\r\\n\\r\\nSlide d\u01b0\u1edbi \u0111\xe2y m\xf4 t\u1ea3 to\xe0n b\u1ed9 quy tr\xecnh x\xe2y d\u1ef1ng website,\\r\\nt\u1eeb b\u01b0\u1edbc kh\u1edfi t\u1ea1o project cho \u0111\u1ebfn khi deploy (tri\u1ec3n khai) website l\xean GitHub Pages.\\r\\n\\r\\n Xem slide h\u01b0\u1edbng d\u1eabn chi ti\u1ebft t\u1ea1i \u0111\xe2y:\\r\\n- \ud83d\udd17 https://www.canva.com/design/DAG-x-HN2J0/AXmxIe_VDDip6aalEPP8PQ/view\\r\\n\\r\\n(Slide s\u1ebd m\u1edf \u1edf tab m\u1edbi \u0111\u1ec3 xem \u0111\u1ea7y \u0111\u1ee7 v\xe0 r\xf5 r\xe0ng h\u01a1n)\\r\\n\\r\\n---\\r\\n\\r\\n## 4. K\u1ebft lu\u1eadn\\r\\nSau khi xem slide, ng\u01b0\u1eddi m\u1edbi c\xf3 th\u1ec3:\\r\\n\\r\\n- T\u1ea1o project Docusaurus\\r\\n- Vi\u1ebft b\xe0i blog\\r\\n- \u0110\u1ea9y source code l\xean GitHub\\r\\n- Deploy website b\u1eb1ng GitHub Pages\\r\\n\\r\\n---"}]}}')}}]);